patches=json.loads(r'''[["app.js","052daf244d7e86a2174b528a614b1cf0397a704268e83b7fb310aeaf857d7c68",[[1242,1242,"const MOCHI_AVATAR = 'mochi-flat-avatar.svg?v=5.5.1';\nfunction photoSource(url){\n  return url==='__builtin__'||/^(?:\\.\\/)?mochi-(?:builtin\\.webp|flat\\.svg)(?:\\?[^#]*)?$/.test(url)?BUILTIN_PHOTO:url;\n}\n"],[1253,1253,"  url=photoSource(url);\n  const flat=url===BUILTIN_PHOTO;\n  if($('stage'))$('stage').dataset.portrait=flat?'flat':'custom';\n  document.querySelectorAll('[data-mochi-avatar]').forEach(img=>{img.src=flat?MOCHI_AVATAR:url;});\n"],[1258,1258,"  paintAcc();\n"],[1260,1260,"  if($('roomImg'))$('roomImg').src=BUILTIN_PHOTO;\n  if($('stage'))$('stage').dataset.portrait='flat';\n  document.querySelectorAll('[data-mochi-avatar]').forEach(img=>{img.src=MOCHI_AVATAR;});\n  paintAcc();\n"],[1270,1271,"  const local=lsGet(PHOTO_KEY)||MEM[PHOTO_KEY];if(local)return photoSource(local);\n"],[1272,1273,"    if(window.storage){ const r = await storageRead(PHOTO_KEY); if(r && r.value) return photoSource(r.value); }\n"],[1274,1275,"  return photoSource(lsGet(PHOTO_KEY) || MEM[PHOTO_KEY] || BUILTIN_PHOTO || '');\n"],[1442,1443,"    .map(sl => worn[sl] ? '<g'+(sl==='neck'&&$('stage').dataset.portrait==='flat'?' transform=\"translate(0 -14)\"':'')+'>'+(ACC_SVG[worn[sl]] || '')+'</g>' : '').join('');\n"],[2467,2467,"$('photoDefault').onclick = ()=>{\n  showPhoto(BUILTIN_PHOTO);savePhoto('__builtin__');\n  $('photoNote').textContent='Illustrated Mochi selected. Learning progress, coins and cat friends are unchanged.';\n};\n"]]],["index.html","1ecd499b5505fad5152c64bedd01f32e4029efbfd4814ef908b400da41314c7b",[[359,360,"<div class=\"mochi-watermarks\" aria-hidden=\"true\"><img decoding=\"async\" class=\"watermark-cat cat-right\" src=\"mochi-flat-avatar.svg?v=5.5.1\" alt=\"\" draggable=\"false\"><img decoding=\"async\" class=\"watermark-cat cat-left\" src=\"mochi-flat-avatar.svg?v=5.5.1\" alt=\"\" draggable=\"false\"></div>\n"],[366,367,"        <img id=\"catImg\" alt=\"\" src=\"mochi-flat.svg?v=5.5.1\" />\n"],[464,465,"<nav class=\"floating-dock instrument-rail\" id=\"focusDock\" aria-label=\"Studio navigation\"><button id=\"focusThink\" class=\"dock-item \" aria-label=\"Think\" aria-controls=\"thinkPanel\" aria-expanded=\"false\"><span class=\"dock-icon\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m15 5 4 4M4 20l4-1 12-12a2.8 2.8 0 0 0-4-4L4 15v5Z\"/></svg></span><span class=\"dock-label\">Think</span></button><button id=\"coachFloat\" class=\"tutor-orb\" aria-label=\"Ask Mochi\" aria-controls=\"coachCard\" aria-expanded=\"false\"><span class=\"tutor-avatar\"><img data-mochi-avatar src=\"mochi-flat-avatar.svg?v=5.5.1\" alt=\"\" width=\"44\" height=\"44\"></span><span class=\"tutor-orb-label\">Ask Mochi</span><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 5h16v11H9l-5 4V5Z\"/><path d=\"M8 9h8M8 12h5\"/></svg></button></nav>\n"],[532,534,"      <div class=\"stage\" id=\"stage\" data-portrait=\"flat\" role=\"button\" tabindex=\"0\" aria-label=\"Pet Mochi\">\n        <img id=\"roomImg\" alt=\"\" src=\"mochi-flat.svg?v=5.5.1\" />\n"],[634,635,"    <div class=\"coach-head\"><img data-mochi-avatar src=\"mochi-flat-avatar.svg?v=5.5.1\" alt=\"\" width=\"48\" height=\"48\"><div><h2>Mochi</h2><span>Your thinking partner</span></div><button id=\"coachClose\" class=\"icon-button\" aria-label=\"Close tutor\">×</button></div>\n"],[683,684,"        <p id=\"releaseNotes\">2D Mochi now matches his cat friends: rounded shapes, big green eyes and a simple brown-tabby coat. The room, tutor portraits and background use the same artwork. 3D cats, learning progress, coins, unlocks and saved custom photos are unchanged.</p>\n"],[696,697,"        <button class=\"btn quiet\" id=\"photoDefault\">Use illustrated Mochi</button>\n        <button class=\"btn quiet\" id=\"photoClear\">Remove photo</button>\n"],[698,699,"      <p class=\"pnote\" id=\"photoNote\">The illustrated Mochi matches his cat friends. Custom photos are optional and kept on this device. A cut-out PNG with a transparent background looks best. It is resized to 400px and stored on this device only.</p>\n"]]],["scripts/release.cjs","e0f087f9cc263d57e736affbc772698b7404888f896f782aab923ed7f6f1c292",[[31,32,"    const core = ['./index.html', './manifest.webmanifest', './euna-avatar.webp',\n"],[35,36,"      ...Array.from(html.matchAll(/(?:src|href)=\"([^\"]+\\.(?:js|css|png|svg)(?:\\?[^\"]*)?)\"/g), m => './' + m[1]).filter(x => !x.includes('://'))];\n"]]],["package.json","636395e7760cf74358553a21a89e889d47e1d8e215304eb815d7177b13bac266",[[5,6,"    \"check:release\": \"node scripts/release.cjs --check && node scripts/build-cat-portraits.cjs --check\",\n"]]],["tests/fixtures/startup.cjs","21647532018a209be091c281cda0589ba0f22c8e31c32e0631d1e0978cc55600",[[212,213," assert.ok(w.document.getElementById('roomImg').src.includes('mochi-flat.svg?v='+version),'Mochi uses the shared flat illustration');\n"]]],["docs/CAT_FRIENDS.md","fa3de58295035aa0292fc0e054c5133a8bec918bcfe10c4c9f988f1e43af0c12",[[46,46,"\n## Shared 2D appearance — v5.5.2\n\n`cat-portraits.js` is the single flat portrait renderer. The four friends keep\nexactly their earlier geometry; Mochi adds brown-tabby marks, green eyes, a white\nmuzzle and paws, and a blue collar. Run `node scripts/build-cat-portraits.cjs`\nafter changing the portrait. Release validation checks its two generated SVGs.\nDefault room/tutor/background images use these versioned SVGs and work offline.\nA previously chosen custom photo remains a deliberate override; the parent-only\n“Use illustrated Mochi” control returns to the current built-in artwork. No photo\nor learning storage key is deleted during the upgrade. 3D is unchanged.\n"]]],["CHANGELOG.md","aa281aa7ebc87ec4bf38f3950d66787a07778fdf1c95ba46fc4353fd9fc328db",[[0,0,"# v5.5.2 — A consistent 2D cat family\n\n- Render Mochi with the same flat, rounded, big-eyed portrait renderer as his friends.\n  Keep his brown tabby markings, white muzzle/paws, green eyes and blue collar.\n- Use generated SVG assets for the picture room, tutor controls and background.\n  Precache versioned SVGs so an old unversioned illustration cannot linger offline.\n- Preserve saved custom photos and add an explicit “Use illustrated Mochi” control.\n  Reposition neck accessories for the full-body portrait without changing ownership.\n- Leave all 3D meshes, progress, coins and companion unlock thresholds unchanged.\n- Check generated artwork consistency, saved-photo behaviour and real picture-mode UI.\n\n"]]],["README.md","ad12a7b63f1ae405df8829da7e6a4a52d4a797940c068e689c4f2dc2c150f97b",[[7,8,"**v5.5.2 — 25 September 2026.** The 2D room, tutor portraits and background now use a flat, rounded Mochi that matches his friends. Custom photos remain optional; the parent settings include **Use illustrated Mochi**. The 3D models and learning rewards are unchanged.\n\n**Cat Friends:** Mochi now has four cat friends: Miso (British Shorthair), Suki (Siamese), Kumo (Maine Coon) and Yuki (Ragdoll). Open **Mochi’s room → Cat Friends** to invite up to three companions. Earned milestone thresholds are 2, 8, 18 and 32; coins and learning scores are unchanged. The new models share the existing renderer, with picture-mode companions as a fallback. Roster preferences are included in backup and family sync.\n"]]]]''')
for name,expected,edits in patches:
    p=Path(name);raw=p.read_bytes()
    assert hashlib.sha256(raw).hexdigest()==expected,'Baseline changed: '+name
    lines=raw.decode().splitlines(keepends=True)
    for start,end,text in reversed(edits):lines[start:end]=[text]
    p.write_bytes(''.join(lines).encode())
p=Path('cat-friends-ui.js');raw=p.read_bytes()
assert hashlib.sha256(raw).hexdigest()=='2493cc1a51c6e015c767f7f8632a71d32583864c8537eef02e5cd91d13b7b3ed','Friend UI baseline changed'
s=raw.decode();a=s.index('function portrait(cat){');b=s.index('\nfunction init(){',a)
p.write_text(s[:a]+'/* GENERATED PORTRAIT START */\n/* GENERATED PORTRAIT END */'+s[b:])
subprocess.run(['node','scripts/build-cat-portraits.cjs'],check=True)
subprocess.run(['node','scripts/release.cjs'],check=True)
